import{_ as t,o as r,c as l,a2 as e}from"./chunks/framework.E8pQZ6KS.js";const p=JSON.parse('{"title":"虚拟机与 Kali","description":"","frontmatter":{},"headers":[],"relativePath":"必学工具/虚拟机与Kali.md","filePath":"必学工具/虚拟机与Kali.md","lastUpdated":1792430298000}'),i={name:"必学工具/虚拟机与Kali.md"};function o(d,a,n,s,h,c){return r(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="虚拟机与-kali" tabindex="-1">虚拟机与 Kali <a class="header-anchor" href="#虚拟机与-kali" aria-label="Permalink to &quot;虚拟机与 Kali&quot;">​</a></h1><blockquote><p>安全人的「移动实验室」。Kali Linux 是业内最知名的渗透测试发行版，内置数百款安全工具，配合虚拟机使用可以随时搭建 / 销毁实验环境。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>校内实训（网络攻防、操作系统安全）和校外 CTF、渗透练习都围绕 Linux 安全环境展开；</li><li>虚拟机（VirtualBox / VMware）提供<strong>隔离 + 快照</strong>能力：环境搞坏了随时回滚，做攻击实验不污染日常系统；</li><li>Kali 预装 Nmap、Metasploit、Burp Suite、Wireshark 等主流工具，省去逐个安装。</li></ul><h2 id="入门路径" tabindex="-1">入门路径 <a class="header-anchor" href="#入门路径" aria-label="Permalink to &quot;入门路径&quot;">​</a></h2><ol><li><strong>安装虚拟机软件</strong>：VirtualBox（免费开源）或 VMware Workstation Player（免费个人版）；</li><li><strong>安装 Kali</strong>：从 <a href="https://www.kali.org/" target="_blank" rel="noreferrer">Kali 官网</a> 下载镜像安装，或直接使用官方提供的 VirtualBox 镜像；</li><li><strong>搭一套靶场</strong>：在同一虚拟网络中架设 Metasploitable 2 / DVWA 等靶机（见 <a href="./../实验与实践/安全实验平台.html">安全实验平台</a>）；</li><li>学会用<strong>快照</strong>：每次实验前打快照，翻车一键还原。</li></ol><h2 id="常用工具速览-kali-内置" tabindex="-1">常用工具速览（Kali 内置） <a class="header-anchor" href="#常用工具速览-kali-内置" aria-label="Permalink to &quot;常用工具速览（Kali 内置）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>工具</th></tr></thead><tbody><tr><td>信息收集</td><td>Nmap、masscan、theHarvester</td></tr><tr><td>漏洞利用</td><td>Metasploit Framework、SearchSploit</td></tr><tr><td>Web 安全</td><td>Burp Suite（社区版）、sqlmap、nikto、dirb</td></tr><tr><td>密码攻击</td><td>Hydra、John the Ripper、hashcat</td></tr><tr><td>网络分析</td><td>Wireshark、tcpdump、nmap 脚本</td></tr><tr><td>逆向 / 调试</td><td>GDB、radare2 / Ghidra</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>先系统学 <a href="./Linux.html">Linux 与命令行</a>，再玩 Kali，事半功倍；</li><li><strong>只在授权环境使用</strong>这些工具——校内实训平台、自建靶场、CTF 平台都可以，未授权目标绝对不行；</li><li>不要只「装个 Kali 看看」，要带着任务用：完成一次「信息收集 → 漏洞发现 → 利用 → 报告」的全流程。</li></ul><h2 id="合规提醒" tabindex="-1">合规提醒 <a class="header-anchor" href="#合规提醒" aria-label="Permalink to &quot;合规提醒&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Kali 及其工具集是双刃剑。请严格遵守 <a href="./../安全方向/法律伦理与合规.html">网络安全法律与伦理</a> 的要求，任何未授权扫描与攻击行为都涉嫌违法。</p></div>',12)])])}const m=t(i,[["render",o]]);export{p as __pageData,m as default};
